package org.ssssssss.magicapi.iot.transport.websocket;
import io.netty.bootstrap.ServerBootstrap; import io.netty.buffer.Unpooled; import io.netty.channel.*; import io.netty.channel.nio.NioEventLoopGroup; import io.netty.channel.socket.SocketChannel; import io.netty.channel.socket.nio.NioServerSocketChannel; import io.netty.handler.codec.http.*; import io.netty.handler.codec.http.websocketx.*; import org.ssssssss.magicapi.iot.core.model.*; import org.ssssssss.magicapi.iot.core.spi.*; import java.net.*; import java.nio.*; import java.nio.charset.StandardCharsets; import java.util.Map; import java.util.concurrent.ConcurrentHashMap; import java.util.concurrent.atomic.AtomicLong;
public final class NettyWebSocketTransportProvider implements ObservableTransportProvider { private final WebSocketTransportProperties p; private final EventLoopGroup boss=new NioEventLoopGroup(1),workers=new NioEventLoopGroup(); private final Map<String,Channel> channels=new ConcurrentHashMap<>(); private final Map<String,ProtocolContext> contexts=new ConcurrentHashMap<>(); private final AtomicLong accepted=new AtomicLong(),received=new AtomicLong(),receivedBytes=new AtomicLong(),sent=new AtomicLong(),sentBytes=new AtomicLong(),errors=new AtomicLong(); private volatile Channel server; private volatile int boundPort; private volatile TransportMessageHandler handler; public NettyWebSocketTransportProvider(WebSocketTransportProperties p){this.p=p;} public String transportId(){return "websocket";}
public synchronized void start(TransportMessageHandler h){if(isRunning())return;handler=h;server=new ServerBootstrap().group(boss,workers).channel(NioServerSocketChannel.class).childHandler(new ChannelInitializer<SocketChannel>(){protected void initChannel(SocketChannel c){c.pipeline().addLast(new HttpServerCodec(),new HttpObjectAggregator(p.getMaxFrameSize()),new WebSocketServerProtocolHandler(p.getPath(),null,true,p.getMaxFrameSize()),new Inbound());}}).bind(p.getHost(),p.getPort()).syncUninterruptibly().channel();boundPort=((InetSocketAddress)server.localAddress()).getPort();}
public void send(String id,ByteBuffer payload){Channel c=channels.get(id);if(c==null||!c.isActive())throw new IllegalArgumentException("Unknown WebSocket connection: "+id);ByteBuffer source=payload.asReadOnlyBuffer();int n=source.remaining();c.writeAndFlush(new BinaryWebSocketFrame(Unpooled.wrappedBuffer(source))).addListener(f->{if(f.isSuccess()){sent.incrementAndGet();sentBytes.addAndGet(n);}else errors.incrementAndGet();});}
public void disconnect(String id){Channel c=channels.get(id);if(c!=null)c.close();}public boolean isRunning(){return server!=null&&server.isActive();}public TransportSnapshot snapshot(){return new TransportSnapshot(transportId(),isRunning(),p.getHost(),boundPort,channels.size(),accepted.get(),received.get(),receivedBytes.get(),sent.get(),sentBytes.get(),errors.get());} public synchronized void close(){channels.values().forEach(Channel::close);if(server!=null)server.close().awaitUninterruptibly();boss.shutdownGracefully().awaitUninterruptibly();workers.shutdownGracefully().awaitUninterruptibly();channels.clear();contexts.clear();boundPort=0;}
private final class Inbound extends SimpleChannelInboundHandler<WebSocketFrame>{public void userEventTriggered(ChannelHandlerContext c,Object event)throws Exception{if(event==WebSocketServerProtocolHandler.ServerHandshakeStateEvent.HANDSHAKE_COMPLETE){String id=c.channel().id().asLongText();String remote=String.valueOf(c.channel().remoteAddress());ProtocolContext context=new ProtocolContext(transportId(),remote,new DeviceIdentity(p.getProtocolId(),id),Map.of("connectionId",id,"protocolId",p.getProtocolId()));channels.put(id,c.channel());contexts.put(id,context);accepted.incrementAndGet();handler.connected(id,context);}super.userEventTriggered(c,event);}protected void channelRead0(ChannelHandlerContext c,WebSocketFrame frame){String id=c.channel().id().asLongText();byte[] bytes;if(frame instanceof TextWebSocketFrame text)bytes=text.text().getBytes(StandardCharsets.UTF_8);else if(frame instanceof BinaryWebSocketFrame){bytes=new byte[frame.content().readableBytes()];frame.content().getBytes(frame.content().readerIndex(),bytes);}else return;received.incrementAndGet();receivedBytes.addAndGet(bytes.length);handler.received(id,ByteBuffer.wrap(bytes),contexts.get(id));}public void channelInactive(ChannelHandlerContext c){String id=c.channel().id().asLongText();channels.remove(id);ProtocolContext context=contexts.remove(id);if(context!=null)handler.disconnected(id,context,null);}public void exceptionCaught(ChannelHandlerContext c,Throwable cause){errors.incrementAndGet();c.close();}}}
